CREATE TABLE cardex (date TEXT PRIMARY KEY, jdn INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', note_time TEXT NOT NULL DEFAULT '', rest_enabled INTEGER NOT NULL DEFAULT 0, rest_start TEXT NOT NULL DEFAULT '', rest_end TEXT NOT NULL DEFAULT '', leave_enabled INTEGER NOT NULL DEFAULT 0, leave_start TEXT NOT NULL DEFAULT '', leave_end TEXT NOT NULL DEFAULT '', swap_enabled INTEGER NOT NULL DEFAULT 0, swap_note TEXT NOT NULL DEFAULT '', swap_time TEXT NOT NULL DEFAULT '', overtime_enabled INTEGER NOT NULL DEFAULT 0, overtime_start TEXT NOT NULL DEFAULT '', overtime_end TEXT NOT NULL DEFAULT '')